&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;baseTileCount&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nx"&gt;roomAreaSqFt&lt;/span&gt; &lt;span class="o"&gt;/&lt;/span&gt; &lt;span class="nx"&gt;tileAreaSqFt&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;

