&lt;span class="kd"&gt;const&lt;/span&gt; &lt;span class="nx"&gt;totalTiles&lt;/span&gt; &lt;span class="o"&gt;=&lt;/span&gt; &lt;span class="nx"&gt;baseTileCount&lt;/span&gt; &lt;span class="o"&gt;*&lt;/span&gt; &lt;span class="p"&gt;(&lt;/span&gt;&lt;span class="mi"&gt;1&lt;/span&gt; &lt;span class="o"&gt;+&lt;/span&gt; &lt;span class="nx"&gt;wastePercentApplied&lt;/span&gt;&lt;span class="p"&gt;);&lt;/span&gt;
